def _maxval(A, B, l, r):
    # Both operations (v + a, v * b with b >= 1) are non-decreasing in v,
    # so tracking the maximum v at each step is exact.
    v = 0
    for i in range(l - 1, r):
        v = max(v + A[i], v * B[i])
    return v


